        SELECT 
        FROM `stock_check_dish`


                AND (
check_no LIKE CONCAT('%', #{query.searchKeyword}, '%')
                OR reason LIKE CONCAT('%', #{query.searchKeyword}, '%')
                OR audit_remark LIKE CONCAT('%', #{query.searchKeyword}, '%')
                )

            AND check_no LIKE CONCAT('%', #{query.checkNo}, '%')
            AND reason LIKE CONCAT('%', #{query.reason}, '%')
            AND audit_remark LIKE CONCAT('%', #{query.auditRemark}, '%')
            AND store_id = #{query.storeId}
            AND dish_id = #{query.dishId}
            AND stock_before = #{query.stockBefore}
            AND stock_after = #{query.stockAfter}
            AND diff = #{query.diff}
            AND status = #{query.status}
            AND creator_id = #{query.creatorId}
            AND auditor_id = #{query.auditorId}
            AND create_time >= CONCAT(#{query.searchBeginTime}, ' 00:00:00')
            AND create_time <= CONCAT(#{query.searchEndTime}, ' 23:59:59')

        ORDER BY id DESC

